const WEEKDAYS = ["日", "一", "二", "三", "四", "五", "六"];

function formatEventDateTime(dateStr, timeStr) {
  if (!dateStr) return "";
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(y, (m || 1) - 1, d || 1);
  const wd = WEEKDAYS[dt.getDay()];
  return `${dateStr} (周${wd})${timeStr ? " " + timeStr : ""}`;
}

