/* ---------- 持久化存储：共享数据走 Google Apps Script，个人数据走浏览器本地存储 ---------- */

// 把这里换成你自己部署的 Google Apps Script Web App 网址（见 GoogleSheetBackend.gs 部署说明）
// 留空（""）则跳过同步，退回到"仅本次浏览器会话内存"的演示模式
const GOOGLE_SHEET_WEBHOOK_URL = "https://script.google.com/macros/s/AKfycbwK-R00QdfzCfDyVgmJ21lanC6UCwBHo97twmrp7s6y3Obx30MEITgQEcylqFwvcuon/exec";

// 共享数据（活动列表 / 公司介绍 / Logo / 相册）：所有人、所有设备看到的都是同一份，
// 存在 Google Sheet 的 AppData 工作表里，通过 Apps Script 读写
// 读取共享数据改用 JSONP（通过 <script> 标签加载，而不是 fetch）：
// Google Apps Script 的返回内容里没办法加上"允许跨域读取"这个标记，
// 用 fetch() 去读它的内容会被浏览器直接拦下（写入不受影响，只有"读"这个动作受限），
// JSONP 是绕开这个限制的经典做法——用加载脚本的方式而不是读取内容的方式来拿数据。
// 统一给所有跟 Google 通信的请求加上"超时机制"：以前是要么成功、要么无限等待，
// 现在改成"等太久就直接放弃"，不会再出现按钮卡在"正在提交…"却怎么都不动的情况。
async function fetchWithTimeout(url, options, timeoutMs = 15000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

function jsonpGetAppData() {
  return new Promise((resolve) => {
    if (!GOOGLE_SHEET_WEBHOOK_URL) { resolve(null); return; }
    const cbName = "rdttCb_" + Date.now() + "_" + Math.floor(Math.random() * 100000);
    let done = false;
    const cleanup = () => {
      delete window[cbName];
      if (script.parentNode) script.parentNode.removeChild(script);
      clearTimeout(timer);
    };
    const timer = setTimeout(() => {
      if (done) return;
      done = true;
      cleanup();
      resolve(null);
    }, 12000);
    window[cbName] = (json) => {
      if (done) return;
      done = true;
      cleanup();
      resolve(json && json.data ? json.data : null);
    };
    const script = document.createElement("script");
    script.src = `${GOOGLE_SHEET_WEBHOOK_URL}?action=getAppData&callback=${cbName}`;
    script.onerror = () => {
      if (done) return;
      done = true;
      cleanup();
      resolve(null);
    };
    document.body.appendChild(script);
  });
}
async function loadShared() {
  return jsonpGetAppData();
}
async function saveShared(payload) {
  if (!GOOGLE_SHEET_WEBHOOK_URL) return { ok: true };
  try {
    const res = await fetchWithTimeout(GOOGLE_SHEET_WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain" },
      body: JSON.stringify({ action: "saveAppData", payload }),
    });
    const data = await res.json();
    return { ok: data.success !== false, message: data.message || "" };
  } catch (err) {
    return { ok: false, message: String(err) };
  }
}

// 个人数据（我的报名记录/消息通知/语言偏好）：只需要留在这台设备上，
// 用浏览器真正的 localStorage（这是标准网页 API，在任何正式部署的网站上都能用）
function loadPersonal(key, fallback) {
  try {
    const raw = localStorage.getItem("rdtt_" + key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}
function savePersonal(key, value) {
  try {
    localStorage.setItem("rdtt_" + key, JSON.stringify(value));
  } catch {}
}

// 图片上传：转存到 Google Drive，返回一个图片网址（图片本身不会存进 Sheet 单元格，见部署说明）
async function uploadImageToDrive(dataUrl, filename) {
  if (!GOOGLE_SHEET_WEBHOOK_URL) return null;
  try {
    const mimeMatch = dataUrl.match(/^data:([^;]+);/);
    const mimeType = mimeMatch ? mimeMatch[1] : "image/jpeg";
    const res = await fetchWithTimeout(GOOGLE_SHEET_WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain" },
      body: JSON.stringify({ action: "uploadImage", base64: dataUrl, mimeType, filename: filename || "image.jpg" }),
    });
    const data = await res.json();
    return data.success ? data.url : null;
  } catch {
    return null;
  }
}


