async function syncRegistrationToSheet(event, info, qty, paymentStatus) {
  if (!GOOGLE_SHEET_WEBHOOK_URL) return { ok: true, blocked: false, message: "" }; // 未配置，跳过同步
  try {
    const res = await fetchWithTimeout(GOOGLE_SHEET_WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain" }, // 用 text/plain 避免触发浏览器的 CORS 预检请求
      body: JSON.stringify({
        eventId: event.id,
        eventTitle: event.title,
        eventDate: event.date,
        eventLocation: event.location,
        name: info?.name || "",
        phone: info?.phone || "",
        email: info?.email || "",
        qty,
        price: event.price * qty,
        cap: event.cap,
        paymentStatus: paymentStatus || "paid",
      }),
    });
    const data = await res.json();
    if (data.success === false) {
      // 服务器明确判定名额不足，中止报名
      return { ok: false, blocked: true, message: data.message || "" };
    }
    return { ok: true, blocked: false, message: "" };
  } catch (err) {
    // 网络/部署问题，不阻断本地演示流程（客人还是能拿到票），只提示同步未成功
    const isTimeout = err && err.name === "AbortError";
    return {
      ok: true, blocked: false,
      message: isTimeout
        ? "（注意：连接 Google 服务器超时，未能同步到 Google Sheet，请稍后在管理后台核对这笔报名）"
        : "（注意：未能同步到 Google Sheet，可能是网络问题或还没有正式部署，请检查配置）",
    };
  }
}

function syncReviewToSheet(event, review) {
  if (!GOOGLE_SHEET_WEBHOOK_URL) return;
  // 尽力同步，不阻断本地演示流程，也不需要等待/读取返回结果
  fetchWithTimeout(GOOGLE_SHEET_WEBHOOK_URL, {
    method: "POST",
    headers: { "Content-Type": "text/plain" },
    body: JSON.stringify({
      action: "addReview",
      eventTitle: event.title,
      rating: review.rating,
      text: review.text,
      photo: review.photo,
    }),
  }).catch(() => {});
}

// 自动翻译：把一份中文内容（比如活动标题/介绍）交给后台翻译成英文，供切换语言时显示。
// texts 是一个 {字段名: 文字} 的对象，一次可以传好几个字段一起翻译，减少请求次数。
// 翻译失败（网络问题等）时返回空对象，调用方应该在拿不到翻译结果时，退回显示原文，不阻断发布/保存流程。
async function translateFields(texts) {
  if (!GOOGLE_SHEET_WEBHOOK_URL) return {};
  try {
    const res = await fetchWithTimeout(GOOGLE_SHEET_WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain" },
      body: JSON.stringify({ action: "translate", texts, target: "en" }),
    });
    const data = await res.json();
    return data.success ? data.translations || {} : {};
  } catch {
    return {};
  }
}

async function geocodeAddress(query) {
  if (!query || !query.trim()) return null;
  try {
    const q = /singapore/i.test(query) ? query : `${query}, Singapore`;
    const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=sg&q=${encodeURIComponent(q)}`);
    const data = await res.json();
    if (data && data[0] && data[0].lat && data[0].lon) {
      return `${data[0].lat},${data[0].lon}`;
    }
  } catch {}
  return null;
}

function buildShareUrl(event) {
  const origin = typeof window !== "undefined" && window.location ? window.location.origin : "";
  return `${origin}/events/${event.id}`;
}
function openWhatsApp(event) {
  const text = encodeURIComponent(`${event.title} · ${event.date} · ${event.location}\n${buildShareUrl(event)}`);
  window.open(`https://wa.me/?text=${text}`, "_blank", "noopener,noreferrer");
}
function openFacebook(event) {
  const url = encodeURIComponent(buildShareUrl(event));
  window.open(`https://www.facebook.com/sharer/sharer.php?u=${url}`, "_blank", "noopener,noreferrer");
}

/* ---------- 导出 Excel ---------- */
function triggerXlsxDownload(wb, filename) {
  const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
  const blob = new Blob([wbout], { type: "application/octet-stream" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}
function exportRegistrationsToExcel(events) {
  const summaryRows = events.map((e) => ({
    活动名称: e.title, 类型: e.type, 标签: e.tag, 日期: e.date, 地点: e.location,
    单价S: e.price, 已报名: e.reg, 容量: e.cap, 预计收入S: e.reg * e.price,
  }));
  const detailRows = [];
  events.forEach((e) => {
    (e.attendees || []).forEach((a) => {
      detailRows.push({
        活动名称: e.title, 日期: e.date, 姓名: a.name || "", 电话: a.phone || "", 电邮: a.email || "",
        人数: a.qty || 1, 签到状态: a.checkedIn ? "已签到" : "待签到",
      });
    });
  });
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(summaryRows), "活动报名情况");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(detailRows), "报名人联系方式");
  triggerXlsxDownload(wb, "红点时光_活动报名情况.xlsx");
}
function exportItineraryToExcel(registrations) {
  if (registrations.length === 0) return false;
  const rows = registrations.map((r) => ({
    活动名称: r.title, 时间: r.date, 地点: r.location, 人数: r.qty || 1, 费用S: r.price,
    联系人: r.name || "", 电话: r.phone || "", 电邮: r.email || "",
  }));
  const ws = XLSX.utils.json_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "我的行程");
  triggerXlsxDownload(wb, "我的红点时光行程.xlsx");
  return true;
}

/* 读取并压缩上传的图片，控制体积（存储有大小限制，也让 App 更流畅） */
function readImageFile(file, cb, maxDim = 900) {
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    const img = new window.Image();
    img.onload = () => {
      let { width, height } = img;
      if (width > maxDim || height > maxDim) {
        if (width > height) { height = Math.round((height * maxDim) / width); width = maxDim; }
        else { width = Math.round((width * maxDim) / height); height = maxDim; }
      }
      const canvas = document.createElement("canvas");
      canvas.width = width; canvas.height = height;
      canvas.getContext("2d").drawImage(img, 0, 0, width, height);
      cb(canvas.toDataURL("image/jpeg", 0.82));
    };
    img.src = reader.result;
  };
  reader.readAsDataURL(file);
}

