/* ---------- 客服聊天 ---------- */
function ChatScreen({ contacts, t, lang, setLang }) {
  const [msgs, setMsgs] = useState([{ from: "bot", text: t("您好,我是红点小助手,有什么可以帮您?", "Hi, I'm the Red Dot assistant — how can I help you?") }]);
  const [input, setInput] = useState("");
  const [viewing, setViewing] = useState(null);
  const faqEntries = [
    {
      q: t("如何取消报名？", "How do I cancel a booking?"),
      a: t(
        "可以的～打开「我的」→「我的报名记录」，找到对应的活动，点击「取消报名」即可，名额会自动还给其他人。取消后这笔记录会从你的报名列表里移除；如果已经完成支付，请联系我们协助退款。",
        "Sure — go to \"Me\" → \"My Bookings\", find the booking, and tap \"Cancel Booking\". The spot is automatically released for others, and it's removed from your bookings list. If you've already paid, please contact us to help with a refund."
      ),
    },
    {
      q: t("PayNow 支付失败怎么办？", "What if my PayNow payment fails?"),
      a: t("已收到您的问题,人工客服将在 5 分钟内回复您～（演示回复）", "Got your question — a support agent will reply within 5 minutes (demo reply)"),
    },
  ];
  const faqs = faqEntries.map((f) => f.q);
  const send = (text) => {
    if (!text.trim()) return;
    setMsgs((m) => [...m, { from: "user", text }]);
    setInput("");
    const matched = faqEntries.find((f) => f.q === text);
    const reply = matched ? matched.a : t("已收到您的问题,人工客服将在 5 分钟内回复您～（演示回复）", "Got your question — a support agent will reply within 5 minutes (demo reply)");
    setTimeout(() => setMsgs((m) => [...m, { from: "bot", text: reply }]), 500);
  };
  return (
    <div className="flex flex-col h-full" style={{ position: "relative" }}>
      <TopBar title={t("在线客服", "Live Support")} lang={lang} setLang={setLang} />
      {(() => {
        const chatContacts = (contacts || []).filter((c) => !c.showOn || c.showOn === "chat" || c.showOn === "both");
        return chatContacts.length > 0 && (
        <div className="px-4 pt-3 pb-1 border-b border-[#EFE7D6]">
          <p className="text-[11px] text-[#6B6456] mb-2">{t("扫码添加我们", "Scan to contact us")}</p>
          <div className="flex gap-2.5 overflow-x-auto pb-1">
            {chatContacts.map((c, i) => (
              <button key={i} onClick={() => setViewing(c)} className="shrink-0 flex flex-col items-center gap-1">
                <div className="w-16 h-16 rounded-lg overflow-hidden bg-[#F6F1E7] border border-[#E7DFCC] flex items-center justify-center">
                  <img src={c.qr} alt={c.label} className="w-full h-full object-contain" />
                </div>
                <span className="text-[10px] text-[#6B6456]">{c.label}</span>
              </button>
            ))}
          </div>
        </div>
        );
      })()}
      <div className="flex-1 px-4 py-4 flex flex-col gap-2.5 overflow-y-auto">
        {msgs.map((m, i) => (
          <div key={i} className={`max-w-[75%] px-3.5 py-2 rounded-2xl text-[12.5px] ${m.from === "bot" ? "bg-[#F1EAD9] self-start text-[#1F2430]" : "bg-[#3E567D] text-[#F6F1E7] self-end"}`}>{m.text}</div>
        ))}
      </div>
      <div className="px-4 flex gap-2 flex-wrap mb-2">
        {faqs.map((f) => <button key={f} onClick={() => send(f)} className="text-[11px] px-2.5 py-1.5 rounded-full bg-[#F6F1E7] border border-[#E7DFCC] text-[#6B6456]">{f}</button>)}
      </div>
      <div className="px-4 py-3 border-t border-[#EFE7D6] flex items-center gap-2">
        <input value={input} onChange={(e) => setInput(e.target.value)} placeholder={t("输入您的问题...", "Type your question...")} className="flex-1 bg-[#F1EAD9] rounded-full px-4 py-2.5 text-[12.5px] outline-none" />
        <button onClick={() => send(input)} className="p-2.5 rounded-full" style={{ background: "#E8432D" }}><Send size={14} color="#fff" /></button>
      </div>
      {viewing && (
        <div
          onClick={() => setViewing(null)}
          style={{ position: "fixed", inset: 0, zIndex: 999, background: "rgba(0,0,0,0.9)" }}
          className="flex flex-col items-center justify-center p-6"
        >
          <div className="bg-white rounded-2xl p-4 max-w-[280px] w-full">
            <img src={viewing.qr} alt={viewing.label} className="w-full h-auto" />
          </div>
          <p className="text-white text-[13px] mt-3">{viewing.label}</p>
          <button onClick={() => setViewing(null)} className="absolute top-4 right-4 text-white text-[13px] bg-white/15 rounded-full w-9 h-9 flex items-center justify-center">✕</button>
        </div>
      )}
    </div>
  );
}

/* ---------- 后台分析 ---------- */
function AdminScreen({ events, addEvent, updateEvent, deleteEvent, toggleAttendee, intro, introEn, logo, photos, onSaveIntro, notify, setEventCoords, relocateAllEvents, activeMembers, setActiveMembers, resetStats, contacts, setContacts, sharedSyncBlocked, t, lang, setLang }) {
  const [view, setView] = useState("main");
  const [coordsEventId, setCoordsEventId] = useState(null);
  const [editEventId, setEditEventId] = useState(null);
  const [templateEventId, setTemplateEventId] = useState(null);

  if (view === "publish") {
    const tmpl = templateEventId ? events.find((e) => e.id === templateEventId) : null;
    return (
      <EventFormScreen
        mode="create"
        initial={tmpl ? { ...tmpl, date: "" } : undefined}
        templateTitle={tmpl?.title}
        t={t} lang={lang} setLang={setLang}
        onBack={() => { setView("main"); setTemplateEventId(null); }}
        onSubmit={(f) => {
          addEvent(f);
          setTemplateEventId(null);
          notify(f.geocodeFailed ? t("已发布，之后可在下方列表里点定位图标手动修正坐标", "Published — you can fix the coordinates from the pin icon in the list below") : t("新活动已发布，可在首页查看", "New event published — you can see it on the home page"));
        }}
      />
    );
  }
  if (view === "editEvent") {
    const ev = events.find((e) => e.id === editEventId);
    if (!ev) return null;
    return (
      <EventFormScreen
        mode="edit"
        initial={ev}
        t={t} lang={lang} setLang={setLang}
        onBack={() => setView("main")}
        onSubmit={(f) => {
          updateEvent(ev.id, f);
          notify(t("活动信息已更新", "Event details updated"));
        }}
      />
    );
  }
  if (view === "scanner") return <CheckinScannerScreen events={events} onBack={() => setView("main")} onToggle={toggleAttendee} t={t} lang={lang} setLang={setLang} />;
  if (view === "editIntro")
    return (
      <EditIntroScreen
        intro={intro} introEn={introEn} logo={logo} photos={photos} onBack={() => setView("main")}
        t={t} lang={lang} setLang={setLang}
        onSave={(text, textEn, newLogo, newPhotos) => { onSaveIntro(text, textEn, newLogo, newPhotos); notify(t("公司介绍已更新", "Company profile updated")); }}
      />
    );
  if (view === "editCoords") {
    const ev = events.find((e) => e.id === coordsEventId);
    if (!ev) return null;
    return (
      <EditCoordsScreen
        event={ev} onBack={() => setView("main")}
        t={t} lang={lang} setLang={setLang}
        onSave={(coords) => { setEventCoords(ev.id, coords); notify(t("坐标已更新", "Coordinates updated")); }}
      />
    );
  }
  if (view === "manageContacts")
    return (
      <ManageContactsScreen
        contacts={contacts} onBack={() => setView("main")}
        t={t} lang={lang} setLang={setLang}
        onSave={(newContacts) => { setContacts(newContacts); notify(t("联系方式已更新", "Contact details updated")); }}
      />
    );

  const totalReg = events.reduce((s, e) => s + e.reg, 0);
  const revenue = events.reduce((s, e) => s + e.reg * e.price, 0);

  return (
    <div className="pb-6">
      <TopBar title={t("管理后台", "Admin")} right={<ShieldCheck size={18} color="#C69A3E" />} lang={lang} setLang={setLang} />
      {sharedSyncBlocked && (
        <div className="mx-4 mt-3 px-3.5 py-2.5 rounded-xl" style={{ background: "#FBE4DF" }}>
          <p className="text-[11.5px] text-[#B23A2A]">
            {t(
              "⚠️ 未能连接到数据服务，当前显示的可能不是最新内容。为避免覆盖真实数据，这次打开期间的改动不会自动保存，建议刷新页面后重试，确认恢复正常后再操作。",
              "⚠️ Couldn't connect to the data service — what you see may be out of date. To avoid overwriting real data, changes made this session won't auto-save. Please refresh and confirm it's connected before making changes."
            )}
          </p>
        </div>
      )}
      <div className="px-4 pt-4 grid grid-cols-2 gap-3">
        {[
          { label: t("累计报名人数", "Total Bookings"), value: totalReg, icon: Users },
          { label: t("累计收入 (S$)", "Total Revenue (S$)"), value: revenue, icon: TrendingUp },
          {
            label: t("活跃会员", "Active Members"), value: activeMembers, icon: User,
            onClick: () => {
              const val = window.prompt(t("输入活跃会员数", "Enter active member count"), String(activeMembers));
              if (val !== null && !isNaN(Number(val))) setActiveMembers(Math.max(0, Math.round(Number(val))));
            },
          },
          { label: t("本月活动数", "Events This Month"), value: events.length, icon: Ticket },
        ].map((c, i) => {
          const Icon = c.icon;
          const Wrapper = c.onClick ? "button" : "div";
          return (
            <Wrapper key={i} onClick={c.onClick} className="bg-[#FFFDF8] rounded-xl p-3.5 border border-[#EFE7D6] text-left">
              <Icon size={16} color="#E8432D" />
              <p className="text-[19px] font-semibold text-[#1F2430] mt-1.5">{c.value}</p>
              <p className="text-[10.5px] text-[#6B6456]">{c.label}{c.onClick && <Pencil size={9} className="inline ml-1" />}</p>
            </Wrapper>
          );
        })}
      </div>
      <div className="px-4 mt-3">
        <button onClick={resetStats} className="w-full flex items-center justify-center gap-1.5 py-2 rounded-full border border-[#C9973E] text-[11.5px] text-[#C69A3E]">
          <RotateCcw size={12} /> {t("清零所有统计数据", "Reset All Stats")}
        </button>
      </div>
      <div className="px-4 mt-5">
        <div className="flex items-center justify-between mb-2">
          <h3 className="text-[13px] font-semibold text-[#1F2430] flex items-center gap-1.5"><QrCode size={14} color="#E8432D" /> {t("活动报名情况", "Event Bookings")}</h3>
          <button onClick={() => exportRegistrationsToExcel(events)} className="flex items-center gap-1 text-[11px] text-[#E8432D] border border-[#E8432D] px-2.5 py-1 rounded-full"><Download size={12} /> {t("导出 Excel", "Export Excel")}</button>
        </div>
        <div className="bg-[#FFFDF8] rounded-xl border border-[#EFE7D6] overflow-hidden">
          {events.map((e, i) => (
            <div key={e.id} className={`flex items-center justify-between px-3.5 py-3 text-[12px] gap-2 ${i !== 0 ? "border-t border-[#EFE7D6]" : ""}`}>
              <span className="text-[#1F2430] truncate flex-1">{e.title}</span>
              <button
                onClick={() => deleteEvent(e.id, e.title)}
                title={t("删除活动", "Delete event")}
                className="shrink-0 text-[#6B6456] p-1"
              >
                <Trash2 size={13} />
              </button>
              <button
                onClick={() => { setTemplateEventId(e.id); setView("publish"); }}
                title={t("用作模板创建新活动", "Use as template for a new event")}
                className="shrink-0 text-[#6B6456] p-1"
              >
                <Copy size={13} />
              </button>
              <button
                onClick={() => { setEditEventId(e.id); setView("editEvent"); }}
                title={t("编辑活动", "Edit event")}
                className="shrink-0 text-[#6B6456] p-1"
              >
                <Pencil size={13} />
              </button>
              <button
                onClick={() => { setCoordsEventId(e.id); setView("editCoords"); }}
                title={t("重新定位坐标", "Fix coordinates")}
                className="shrink-0 text-[#6B6456] p-1"
              >
                <MapPin size={13} />
              </button>
              <div className="flex items-center gap-2 shrink-0">
                <div className="w-16 h-1.5 rounded-full bg-[#EFE7D6] overflow-hidden">
                  <div className="h-full" style={{ width: `${(e.reg / e.cap) * 100}%`, background: e.reg >= e.cap ? "#E8432D" : "#C69A3E" }} />
                </div>
                <span className="text-[#6B6456] text-[11px] w-10 text-right">{e.reg}/{e.cap}</span>
              </div>
            </div>
          ))}
        </div>
        <p className="text-[10px] text-[#6B6456] mt-1.5">{t(
          "若点击\"导出 Excel\"后没有下载提示，可能是当前预览环境限制了文件下载，可在正式部署环境或桌面浏览器中重试。Excel 会包含两个表：活动汇总，以及每一位报名人的姓名/电话/电邮明细，方便直接联系客人。地图坐标不准时，可点每行标题旁的定位图标手动修正（这个环境里自动定位不一定成功，用 Google 地图查坐标再手动填入最准确）。点复制图标可以把这个活动用作模板，快速创建下一场同类活动。",
          "If nothing downloads after tapping \"Export Excel\", this preview environment may be restricting file downloads — try again in a production deployment or a desktop browser. The Excel file includes two sheets: an event summary, and a detail sheet with every attendee's name/phone/email for direct contact. If a map pin looks off, tap the pin icon next to the title to fix it manually (auto-locate isn't always reliable here — looking it up on Google Maps and pasting the coordinates in is the most accurate way). Tap the copy icon to use an event as a template for quickly creating the next occurrence."
        )}</p>
        <button onClick={relocateAllEvents} className="w-full flex items-center justify-center gap-1.5 mt-2 py-2 rounded-full border border-[#C9973E] text-[11.5px] text-[#C69A3E]">
          <MapPin size={12} /> {t("尝试批量自动定位（不一定成功）", "Try bulk auto-locate (not guaranteed)")}
        </button>
      </div>
      <div className="px-4 mt-5 flex flex-col gap-2.5">
        <button onClick={() => { setTemplateEventId(null); setView("publish"); }} className="w-full flex items-center justify-center gap-2 py-3 rounded-full text-[#FFFDF8] text-[12.5px] font-medium" style={{ background: "#E8432D" }}><Plus size={15} /> {t("发布新活动", "Publish New Event")}</button>
        <button onClick={() => setView("scanner")} className="w-full flex items-center justify-center gap-2 py-3 rounded-full border border-[#3E567D] text-[12.5px] text-[#3E567D]"><QrCode size={15} /> {t("打开现场签到扫码器", "Open On-Site Check-In Scanner")}</button>
        <button onClick={() => setView("manageContacts")} className="w-full flex items-center justify-center gap-2 py-3 rounded-full border border-[#3E567D] text-[12.5px] text-[#3E567D]"><MessageCircle size={15} /> {t("联系方式管理（微信/WhatsApp 二维码）", "Manage Contact QR Codes (WeChat/WhatsApp)")}</button>
      </div>
      <div className="px-4 mt-5">
        <div className="flex items-center justify-between mb-2">
          <h3 className="text-[13px] font-semibold text-[#1F2430]">{t("公司介绍", "Company Profile")}</h3>
          <button onClick={() => setView("editIntro")} className="flex items-center gap-1 text-[11px] text-[#E8432D]"><Pencil size={12} /> {t("编辑", "Edit")}</button>
        </div>
        <div className="bg-[#F6F1E7] rounded-xl p-4 border border-[#EFE7D6] flex items-center gap-3">
          <img src={logo} alt="红点时光" className="w-10 h-10 rounded-full shrink-0 object-cover" />
          <p className="text-[12px] text-[#4A4438] leading-relaxed">{intro}</p>
        </div>
      </div>
    </div>
  );
}

/* ---------- 发布新活动（整屏，日期时间用原生选择器） ---------- */
function parseEventDateTime(dateStr) {
  if (!dateStr) return { dateOnly: "", timeOnly: "" };
  const m = dateStr.match(/(\d{4}-\d{2}-\d{2}).*?(\d{2}:\d{2})/);
  return m ? { dateOnly: m[1], timeOnly: m[2] } : { dateOnly: "", timeOnly: "" };
}
function isPastEvent(event) {
  const { dateOnly, timeOnly } = parseEventDateTime(event.date);
  if (!dateOnly) return false;
  const dt = new Date(`${dateOnly}T${timeOnly || "23:59"}`);
  return dt.getTime() < Date.now();
}

function EventFormScreen({ onBack, onSubmit, initial, mode = "create", templateTitle, t, lang, setLang }) {
  const parsed = parseEventDateTime(initial?.date);
  const [f, setF] = useState({
    type: initial?.type || "城市探索",
    tag: initial?.tag || "",
    title: initial?.title || "",
    dateOnly: parsed.dateOnly,
    timeOnly: parsed.timeOnly,
    location: initial?.location || "",
    price: initial?.price != null ? String(initial.price) : "",
    cap: initial?.cap != null ? String(initial.cap) : "",
    desc: initial?.desc || "",
    image: initial?.image || null,
    coords: initial?.coords || "",
    titleEn: initial?.titleEn || "",
    tagEn: initial?.tagEn || "",
    descEn: initial?.descEn || "",
    originalPrice: initial?.originalPrice != null ? String(initial.originalPrice) : "",
    promoText: initial?.promoText || "",
  });
  const [error, setError] = useState("");
  const [locating, setLocating] = useState(false);
  const [translating, setTranslating] = useState(false);
  const [imgUploading, setImgUploading] = useState(false);
  const [showEnFields, setShowEnFields] = useState(false);
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });

  const retranslate = async () => {
    setTranslating(true);
    const translated = await translateFields({ title: f.title, desc: f.desc, tag: f.tag });
    setTranslating(false);
    setF((prev) => ({
      ...prev,
      titleEn: translated.title || prev.titleEn,
      descEn: translated.desc || prev.descEn,
      tagEn: translated.tag || prev.tagEn,
    }));
    setShowEnFields(true);
  };

  const missing = () => {
    const m = [];
    if (!f.title) m.push(t("活动标题", "Event title"));
    if (!f.dateOnly) m.push(t("日期", "Date"));
    if (!f.timeOnly) m.push(t("时间", "Time"));
    if (!f.location) m.push(t("地点", "Location"));
    if (!f.price) m.push(t("价格", "Price"));
    if (!f.cap) m.push(t("名额", "Capacity"));
    return m;
  };

  const coordsValid = /^-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?$/.test((f.coords || "").trim());

  const handleSubmit = async () => {
    const m = missing();
    if (m.length > 0) { setError(t("请填写：", "Please fill in: ") + m.join(t("、", ", "))); return; }
    setError("");
    let coords = coordsValid ? f.coords.trim() : null;
    if (!coords) {
      setLocating(true);
      coords = await geocodeAddress(f.location);
      setLocating(false);
    }
    // 只翻译还没有内容的字段——如果管理员已经手动填过/改过英文版，不会被自动翻译覆盖掉
    let titleEn = f.titleEn, descEn = f.descEn, tagEn = f.tagEn;
    const needTranslate = {};
    if (!titleEn && f.title) needTranslate.title = f.title;
    if (!descEn && f.desc) needTranslate.desc = f.desc;
    if (!tagEn && f.tag) needTranslate.tag = f.tag;
    if (Object.keys(needTranslate).length > 0) {
      setTranslating(true);
      const translated = await translateFields(needTranslate);
      setTranslating(false);
      titleEn = titleEn || translated.title || "";
      descEn = descEn || translated.desc || "";
      tagEn = tagEn || translated.tag || "";
    }
    onSubmit({
      ...f,
      date: formatEventDateTime(f.dateOnly, f.timeOnly),
      coords: coords || FALLBACK_COORDS,
      geocodeFailed: !coords,
      titleEn,
      descEn,
      tagEn,
    });
    onBack();
  };

  return (
    <div className="h-full flex flex-col" style={{ background: "#FFFDF8" }}>
      <TopBar title={mode === "edit" ? t("编辑活动", "Edit Event") : t("发布新活动", "Publish New Event")} onBack={onBack} lang={lang} setLang={setLang} />
      <div className="flex-1 min-h-0 overflow-y-auto px-5 py-5">
        {templateTitle && (
          <p className="text-[11px] text-[#C69A3E] bg-[#FBF3E0] rounded-lg px-3 py-2 mb-3">
            {t(`基于「${templateTitle}」创建，已带入原有信息，请检查并填写新的日期时间`, `Based on "${templateTitle}" — its details have been pre-filled, please review and set a new date/time`)}
          </p>
        )}
        <div className="flex flex-col gap-2.5">
          <div className="flex gap-2">
            {TYPES.filter((ty) => ty !== "全部").map((ty) => (
              <button key={ty} onClick={() => setF({ ...f, type: ty })} className="flex-1 py-2 rounded-full text-[12px]"
                style={{ background: f.type === ty ? "#E8432D" : "#F1EAD9", color: f.type === ty ? "#fff" : "#4A4438" }}>{typeLabel(t, ty)}</button>
            ))}
          </div>
          <label htmlFor="event-image-input" className="flex items-center gap-2 bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12px] text-[#6B6456] cursor-pointer">
            <ImagePlus size={15} />
            {imgUploading ? t("正在上传图片…", "Uploading photo…") : f.image ? t("已选择活动图片，点击可更换", "Photo selected — tap to change") : t("上传活动图片（可选）", "Upload event photo (optional)")}
            <input
              id="event-image-input" type="file" accept="image/*" className="hidden"
              onChange={(e) => {
                const file = e.target.files?.[0];
                readImageFile(file, async (localUrl) => {
                  setF((prev) => ({ ...prev, image: localUrl }));
                  setImgUploading(true);
                  const remoteUrl = await uploadImageToDrive(localUrl, file?.name);
                  setImgUploading(false);
                  if (remoteUrl) setF((prev) => ({ ...prev, image: remoteUrl }));
                });
              }}
            />
          </label>
          {f.image && (
            <div className="w-full bg-[#F1EAD9] rounded-lg overflow-hidden flex items-center justify-center" style={{ maxHeight: "260px" }}>
              <img src={f.image} alt="preview" className="w-full h-auto object-contain" style={{ maxHeight: "260px" }} />
            </div>
          )}
          <p className="text-[10px] text-[#6B6456] -mt-1">{t("若点击上传后没有反应，可能是当前预览环境限制了文件选择，可在浏览器中打开完整版重试。", "If nothing happens when you tap upload, this preview environment may be restricting file selection — try opening the full version in a browser.")}</p>

          <input placeholder={t("活动标签，如 户外 / 讲座", "Tag, e.g. Outdoor / Talk")} value={f.tag} onChange={set("tag")} className="bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none" />
          <input placeholder={t("活动标题 *", "Event title *")} value={f.title} onChange={set("title")} className="bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none" />

          <div className="flex gap-2">
            <div className="flex-1">
              <label className="text-[11px] text-[#6B6456] mb-1 block">{t("日期 *", "Date *")}</label>
              <input type="date" value={f.dateOnly} onChange={set("dateOnly")} className="w-full bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none" />
            </div>
            <div className="flex-1">
              <label className="text-[11px] text-[#6B6456] mb-1 block">{t("时间 *", "Time *")}</label>
              <input type="time" value={f.timeOnly} onChange={set("timeOnly")} className="w-full bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none" />
            </div>
          </div>

          <input placeholder={t("地点 *", "Location *")} value={f.location} onChange={set("location")} className="bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none" />

          {f.location && (
            <button onClick={() => openMapSearch(f.location)} className="flex items-center justify-center gap-1.5 py-2 rounded-full border border-[#3E567D] text-[11.5px] text-[#3E567D]">
              <MapPin size={13} /> {t("在 Google 地图搜索这个地址，核对坐标", "Search this address on Google Maps to verify coordinates")}
            </button>
          )}
          <div>
            <label className="text-[11px] text-[#6B6456] mb-1 block">{t("精确坐标（可选，纬度,经度）", "Precise coordinates (optional, lat,lng)")}</label>
            <input placeholder={t("例如 1.2868,103.8545（不填会尝试自动定位，但不一定成功）", "e.g. 1.2868,103.8545 (leave blank to try auto-locate — not guaranteed)")} value={f.coords} onChange={set("coords")} className="w-full bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12px] outline-none font-mono" />
            {mode === "edit" && <p className="text-[10px] text-[#6B6456] mt-1">{t("如果改了地点，记得同步核对/更新上面的坐标，坐标不会自动跟着地点变化。", "If you change the location, remember to also review/update the coordinates above — they don't update automatically.")}</p>}
          </div>
          <div className="flex gap-2">
            <input placeholder={t("价格 S$ *", "Price S$ *")} type="number" value={f.price} onChange={set("price")} className="flex-1 bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none" />
            <input placeholder={t("名额 *", "Capacity *")} type="number" value={f.cap} onChange={set("cap")} className="flex-1 bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none" />
          </div>
          <div>
            <label className="text-[11px] text-[#6B6456] mb-1 block">{t("促销（可选）", "Promotion (optional)")}</label>
            <div className="flex gap-2 mb-2">
              <input
                placeholder={t("原价 S$（留空则不显示划线价）", "Original price S$ (leave blank to hide)")}
                type="number" value={f.originalPrice} onChange={set("originalPrice")}
                className="flex-1 bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none"
              />
            </div>
            <input
              placeholder={t("促销文字，如 买一送一 / 早鸟优惠", "Promo text, e.g. Buy 1 Get 1 Free / Early Bird")}
              value={f.promoText} onChange={set("promoText")}
              className="w-full bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none"
            />
            <p className="text-[10px] text-[#6B6456] mt-1">{t("填了「原价」且比「价格」高，会自动算出折扣百分比显示划线价；「促销文字」用来标注买一送一这类没法用折扣百分比表达的活动，两个可以只填一个，也可以都填。", "If \"Original price\" is filled and higher than \"Price\", a discount % badge and struck-through price show automatically. \"Promo text\" is for things like buy-one-get-one that a percentage can't capture — fill in either or both.")}</p>
          </div>
          <textarea placeholder={t("活动介绍", "Description")} value={f.desc} onChange={set("desc")} rows={3} className="bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none resize-none" />

          <button onClick={() => setShowEnFields((s) => !s)} className="flex items-center justify-between text-[11.5px] text-[#3E567D] py-1">
            <span>{t("英文版内容（发布时自动翻译，也可以手动修正）", "English version (auto-translated on publish — you can edit it manually)")}</span>
            <span>{showEnFields ? "▲" : "▼"}</span>
          </button>
          {showEnFields && (
            <div className="flex flex-col gap-2 bg-[#F6F1E7] rounded-lg p-3">
              <input placeholder={t("英文标签", "English tag")} value={f.tagEn} onChange={set("tagEn")} className="bg-white rounded-lg px-3 py-2 text-[12px] outline-none" />
              <input placeholder={t("英文标题", "English title")} value={f.titleEn} onChange={set("titleEn")} className="bg-white rounded-lg px-3 py-2 text-[12px] outline-none" />
              <textarea placeholder={t("英文介绍", "English description")} value={f.descEn} onChange={set("descEn")} rows={3} className="bg-white rounded-lg px-3 py-2 text-[12px] outline-none resize-none" />
              <button onClick={retranslate} disabled={translating} className="self-start flex items-center gap-1 text-[11px] text-[#E8432D] disabled:opacity-60">
                <RotateCcw size={11} /> {translating ? t("翻译中…", "Translating…") : t("重新自动翻译（会覆盖上面的英文内容）", "Re-translate (will overwrite the English text above)")}
              </button>
              <p className="text-[10px] text-[#6B6456]">{t("留空的话，发布时会自动翻译；如果这里已经填了内容，发布时不会被自动翻译覆盖。", "Leave blank to auto-translate on publish; if you've already filled this in, it won't be overwritten automatically.")}</p>
            </div>
          )}
          {error && <p className="text-[11.5px] text-[#E8432D]">{error}</p>}
        </div>
      </div>
      <div className="shrink-0 px-5 py-3 bg-[#FFFDF8] border-t border-[#EFE7D6]">
        <button onClick={handleSubmit} disabled={locating || imgUploading || translating} className="w-full py-3 rounded-full text-[#FFFDF8] font-medium disabled:opacity-60" style={{ background: "#E8432D" }}>
          {imgUploading ? t("图片上传中，请稍候…", "Uploading photo, please wait…") : locating ? t("正在定位地点…", "Locating…") : translating ? t("正在生成英文翻译…", "Generating English translation…") : mode === "edit" ? t("保存修改", "Save Changes") : t("发布活动", "Publish Event")}
        </button>
      </div>
    </div>
  );
}

/* ---------- 编辑公司介绍（整屏，支持上传 Logo） ---------- */
function EditIntroScreen({ intro, introEn, logo, photos, onBack, onSave, t, lang, setLang }) {
  const [text, setText] = useState(intro);
  const [textEn, setTextEn] = useState(introEn || "");
  const [logoPreview, setLogoPreview] = useState(logo);
  const [photoList, setPhotoList] = useState(photos || []);
  const [logoUploading, setLogoUploading] = useState(false);
  const [photoUploading, setPhotoUploading] = useState(false);
  const [translating, setTranslating] = useState(false);

  const handleLogoChange = (file) => {
    readImageFile(file, async (localUrl) => {
      setLogoPreview(localUrl);
      setLogoUploading(true);
      const remoteUrl = await uploadImageToDrive(localUrl, file?.name);
      setLogoUploading(false);
      if (remoteUrl) setLogoPreview(remoteUrl);
    });
  };

  const addPhoto = (file) => {
    readImageFile(file, async (localUrl) => {
      setPhotoList((p) => [...p, localUrl]);
      setPhotoUploading(true);
      const remoteUrl = await uploadImageToDrive(localUrl, file?.name);
      setPhotoUploading(false);
      if (remoteUrl) {
        setPhotoList((p) => p.map((item) => (item === localUrl ? remoteUrl : item)));
      }
    });
  };
  const removePhoto = (idx) => setPhotoList((p) => p.filter((_, i) => i !== idx));
  const busy = logoUploading || photoUploading;

  return (
    <div className="h-full flex flex-col" style={{ background: "#FFFDF8" }}>
      <TopBar title={t("编辑公司介绍", "Edit Company Profile")} onBack={onBack} lang={lang} setLang={setLang} />
      <div className="flex-1 min-h-0 overflow-y-auto px-5 py-5">
        <p className="text-[12px] text-[#6B6456] mb-2">{t("公司 Logo", "Company Logo")}</p>
        <div className="flex items-center gap-3 mb-1">
          <img src={logoPreview} alt="Logo preview" className="w-16 h-16 rounded-full object-cover border border-[#EFE7D6]" />
          <label htmlFor="logo-input" className="flex items-center gap-1.5 text-[12px] text-[#E8432D] border border-[#E8432D] px-3 py-1.5 rounded-full cursor-pointer">
            <ImagePlus size={14} /> {logoUploading ? t("上传中…", "Uploading…") : t("上传新 Logo", "Upload New Logo")}
            <input id="logo-input" type="file" accept="image/*" className="hidden" onChange={(e) => handleLogoChange(e.target.files?.[0])} />
          </label>
        </div>
        <p className="text-[10px] text-[#6B6456] mb-4">{t("若点击上传后没有反应，可能是当前预览环境限制了文件选择，可在浏览器中打开完整版重试。", "If nothing happens when you tap upload, this preview environment may be restricting file selection — try opening the full version in a browser.")}</p>

        <p className="text-[12px] text-[#6B6456] mb-2">{t("公司介绍文字", "Company Description")}</p>
        <textarea value={text} onChange={(e) => setText(e.target.value)} rows={6} className="w-full bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none resize-none mb-3" />

        <p className="text-[12px] text-[#6B6456] mb-2">{t("英文版介绍（保存时如果留空会自动翻译，也可以手动修正）", "English description (auto-translated on save if left blank — you can edit it manually)")}</p>
        <textarea value={textEn} onChange={(e) => setTextEn(e.target.value)} rows={6} className="w-full bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none resize-none mb-1" />
        <button
          onClick={async () => {
            setTranslating(true);
            const translated = await translateFields({ intro: text });
            setTranslating(false);
            if (translated.intro) setTextEn(translated.intro);
          }}
          disabled={translating}
          className="flex items-center gap-1 text-[11px] text-[#E8432D] mb-5 disabled:opacity-60"
        >
          <RotateCcw size={11} /> {translating ? t("翻译中…", "Translating…") : t("重新自动翻译（会覆盖上面的英文内容）", "Re-translate (will overwrite the English text above)")}
        </button>

        <p className="text-[12px] text-[#6B6456] mb-2">{t('公司照片（会显示在"关于我们"页面）', 'Company Photos (shown on the "About Us" page)')}</p>
        <div className="grid grid-cols-3 gap-2 mb-2">
          {photoList.map((p, i) => (
            <div key={i} className="relative rounded-lg overflow-hidden bg-[#F1EAD9]" style={{ aspectRatio: "1/1" }}>
              <img src={p} alt={`photo ${i + 1}`} className="w-full h-full object-cover" />
              <button onClick={() => removePhoto(i)} className="absolute top-1 right-1 bg-[#3E567D]/80 text-white text-[10px] w-5 h-5 rounded-full flex items-center justify-center">✕</button>
            </div>
          ))}
          <label htmlFor="company-photo-input" className="flex flex-col items-center justify-center gap-1 rounded-lg border border-dashed border-[#C9973E] text-[#C69A3E] cursor-pointer" style={{ aspectRatio: "1/1" }}>
            <ImagePlus size={18} />
            <span className="text-[10px]">{photoUploading ? t("上传中…", "Uploading…") : t("添加照片", "Add Photo")}</span>
            <input id="company-photo-input" type="file" accept="image/*" className="hidden" onChange={(e) => { addPhoto(e.target.files?.[0]); e.target.value = ""; }} />
          </label>
        </div>
        <p className="text-[10px] text-[#6B6456]">{t('可以多次点击"添加照片"上传多张。', 'Tap "Add Photo" repeatedly to upload multiple photos.')}</p>
      </div>
      <div className="shrink-0 px-5 py-3 bg-[#FFFDF8] border-t border-[#EFE7D6]">
        <button onClick={() => { onSave(text, textEn, logoPreview, photoList); onBack(); }} disabled={busy} className="w-full py-3 rounded-full text-[#FFFDF8] font-medium disabled:opacity-60" style={{ background: "#E8432D" }}>
          {busy ? t("图片上传中，请稍候…", "Uploading photo, please wait…") : t("保存", "Save")}
        </button>
      </div>
    </div>
  );
}

/* ---------- 修正活动坐标（手动 + 尽力自动） ---------- */
function EditCoordsScreen({ event, onBack, onSave, t, lang, setLang }) {
  const [coords, setCoords] = useState(event.coords || "");
  const [trying, setTrying] = useState(false);
  const [note, setNote] = useState("");

  const tryAuto = async () => {
    setTrying(true);
    setNote("");
    const c = await geocodeAddress(event.location);
    setTrying(false);
    if (c) {
      setCoords(c);
      setNote(t("已尝试自动定位，请核对下方坐标是否准确（这个环境里自动定位不一定能成功）", "Auto-locate attempted — please verify the coordinates below are accurate (not always reliable in this environment)"));
    } else {
      setNote(t("自动定位没有成功，请点上面的按钮去 Google 地图查找后手动填入坐标", "Auto-locate didn't succeed — use the button above to find it on Google Maps and enter the coordinates manually"));
    }
  };

  const isValid = /^-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?$/.test(coords.trim());

  return (
    <div className="h-full flex flex-col" style={{ background: "#FFFDF8" }}>
      <TopBar title={t("修正活动坐标", "Fix Event Coordinates")} onBack={onBack} lang={lang} setLang={setLang} />
      <div className="flex-1 min-h-0 overflow-y-auto px-5 py-5">
        <p className="text-[13px] font-semibold text-[#1F2430] mb-1">{event.title}</p>
        <p className="text-[11px] text-[#6B6456] mb-4">{event.location}</p>

        <button onClick={() => openMapSearch(event.location)} className="w-full flex items-center justify-center gap-2 py-2.5 rounded-full border border-[#3E567D] text-[12.5px] text-[#3E567D] mb-2">
          <MapPin size={14} /> {t("在 Google 地图搜索这个地址", "Search this address on Google Maps")}
        </button>
        <p className="text-[10.5px] text-[#6B6456] mb-4">
          {t("打开后找到准确位置，长按地图上的点，Google 地图会弹出这个点的经纬度（形如 1.2868, 103.8545），复制后粘贴到下面。", "Find the exact spot, then long-press the point on the map — Google Maps will show its coordinates (e.g. 1.2868, 103.8545). Copy them and paste below.")}
        </p>

        <label className="text-[11px] text-[#6B6456] mb-1 block">{t("坐标（纬度,经度）", "Coordinates (lat,lng)")}</label>
        <input
          value={coords} onChange={(e) => setCoords(e.target.value)} placeholder={t("例如 1.2868,103.8545", "e.g. 1.2868,103.8545")}
          className="w-full bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[12.5px] outline-none mb-2 font-mono"
        />
        {!isValid && coords.trim() !== "" && <p className="text-[11px] text-[#E8432D] mb-2">{t('格式应为"纬度,经度"，中间用英文逗号分隔', 'Format should be "lat,lng" separated by a comma')}</p>}

        <button onClick={tryAuto} disabled={trying} className="text-[11.5px] text-[#C69A3E] underline mb-2">
          {trying ? t("正在尝试自动定位…", "Trying auto-locate…") : t("也可以先试试自动定位（不一定成功）", "Or try auto-locate first (not guaranteed)")}
        </button>
        {note && <p className="text-[11px] text-[#6B6456]">{note}</p>}
      </div>
      <div className="shrink-0 px-5 py-3 bg-[#FFFDF8] border-t border-[#EFE7D6]">
        <button
          onClick={() => { if (isValid) { onSave(coords.trim()); onBack(); } }}
          disabled={!isValid}
          className="w-full py-3 rounded-full text-[#FFFDF8] font-medium disabled:opacity-40"
          style={{ background: "#E8432D" }}
        >
          {t("保存坐标", "Save Coordinates")}
        </button>
      </div>
    </div>
  );
}

/* ---------- 联系方式管理（微信/WhatsApp 等二维码） ---------- */
function ManageContactsScreen({ contacts, onBack, onSave, t, lang, setLang }) {
  const [list, setList] = useState((contacts || []).map((c) => ({ showOn: "chat", ...c })));
  const [uploadingIdx, setUploadingIdx] = useState(null);

  const addContact = () => setList((l) => [...l, { label: "", qr: null, showOn: "chat" }]);
  const removeContact = (i) => setList((l) => l.filter((_, idx) => idx !== i));
  const setLabel = (i, label) => setList((l) => l.map((c, idx) => (idx === i ? { ...c, label } : c)));
  const setShowOn = (i, showOn) => setList((l) => l.map((c, idx) => (idx === i ? { ...c, showOn } : c)));

  const handleQrUpload = (i, file) => {
    readImageFile(file, async (localUrl) => {
      setList((l) => l.map((c, idx) => (idx === i ? { ...c, qr: localUrl } : c)));
      setUploadingIdx(i);
      const remoteUrl = await uploadImageToDrive(localUrl, file?.name);
      setUploadingIdx(null);
      if (remoteUrl) setList((l) => l.map((c, idx) => (idx === i ? { ...c, qr: remoteUrl } : c)));
    });
  };

  const showOnOptions = [
    { id: "chat", label: t("客服页", "Support page") },
    { id: "about", label: t("关于我们页", "About Us page") },
    { id: "both", label: t("两者都显示", "Both") },
  ];

  return (
    <div className="h-full flex flex-col" style={{ background: "#FFFDF8" }}>
      <TopBar title={t("联系方式管理", "Manage Contacts")} onBack={onBack} lang={lang} setLang={setLang} />
      <div className="flex-1 min-h-0 overflow-y-auto px-5 py-5">
        <p className="text-[11.5px] text-[#6B6456] mb-4">{t("这里添加的二维码，可以按需要显示在「客服」页面（方便客人直接联系）或「关于我们」页面（比如公司微信公众号），也可以两个页面都显示。", "QR codes added here can be shown on the Support page (for direct contact), the About Us page (e.g. a WeChat official account), or both.")}</p>
        <div className="flex flex-col gap-3">
          {list.map((c, i) => (
            <div key={i} className="bg-[#F6F1E7] rounded-xl p-3.5 border border-[#EFE7D6]">
              <div className="flex items-center gap-2 mb-2.5">
                <input
                  value={c.label} onChange={(e) => setLabel(i, e.target.value)}
                  placeholder={t("名称，如 微信 / WhatsApp / 微信公众号", "Label, e.g. WeChat / WhatsApp / Official Account")}
                  className="flex-1 bg-white rounded-lg px-3 py-2 text-[12.5px] outline-none"
                />
                <button onClick={() => removeContact(i)} className="shrink-0 text-[#E8432D] p-1"><Trash2 size={15} /></button>
              </div>
              {c.qr && (
                <div className="w-28 h-28 rounded-lg overflow-hidden bg-white border border-[#E7DFCC] mb-2 flex items-center justify-center">
                  <img src={c.qr} alt={c.label} className="w-full h-full object-contain" />
                </div>
              )}
              <label className="flex items-center gap-1.5 text-[11.5px] text-[#E8432D] border border-[#E8432D] px-3 py-1.5 rounded-full cursor-pointer w-fit mb-2.5">
                <ImagePlus size={13} /> {uploadingIdx === i ? t("上传中…", "Uploading…") : c.qr ? t("更换二维码", "Replace QR") : t("上传二维码", "Upload QR")}
                <input type="file" accept="image/*" className="hidden" onChange={(e) => handleQrUpload(i, e.target.files?.[0])} />
              </label>
              <p className="text-[10.5px] text-[#6B6456] mb-1.5">{t("显示位置", "Show on")}</p>
              <div className="flex gap-1.5">
                {showOnOptions.map((opt) => (
                  <button
                    key={opt.id}
                    onClick={() => setShowOn(i, opt.id)}
                    className="px-2.5 py-1 rounded-full text-[10.5px]"
                    style={{ background: c.showOn === opt.id ? "#E8432D" : "#FFFDF8", color: c.showOn === opt.id ? "#FFFDF8" : "#6B6456", border: "1px solid #E7DFCC" }}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>
          ))}
          <button onClick={addContact} className="flex items-center justify-center gap-1.5 py-2.5 rounded-full border border-dashed border-[#C9973E] text-[12px] text-[#C69A3E]">
            <Plus size={14} /> {t("添加一个联系方式", "Add a Contact")}
          </button>
        </div>
      </div>
      <div className="shrink-0 px-5 py-3 bg-[#FFFDF8] border-t border-[#EFE7D6]">
        <button onClick={() => { onSave(list.filter((c) => c.label.trim() && c.qr)); onBack(); }} className="w-full py-3 rounded-full text-[#FFFDF8] font-medium" style={{ background: "#E8432D" }}>
          {t("保存", "Save")}
        </button>
      </div>
    </div>
  );
}

function CheckinScannerScreen({ events, onBack, onToggle, t, lang, setLang }) {
  const withPeople = events.filter((e) => (e.attendees || []).length > 0);
  const list = withPeople.length > 0 ? withPeople : events;
  const [activeId, setActiveId] = useState(list[0]?.id);
  const active = events.find((e) => e.id === activeId) || list[0];

  return (
    <div className="h-full flex flex-col" style={{ background: "#FFFDF8" }}>
      <TopBar title={t("现场签到扫码器", "On-Site Check-In Scanner")} onBack={onBack} lang={lang} setLang={setLang} />
      <div className="flex-1 min-h-0 overflow-y-auto px-5 py-5">
        <div className="flex gap-2 overflow-x-auto pb-2 mb-3">
          {events.map((e) => (
            <button key={e.id} onClick={() => setActiveId(e.id)} className="px-3 py-1.5 rounded-full text-[11px] whitespace-nowrap shrink-0"
              style={{ background: active?.id === e.id ? "#3E567D" : "#F1EAD9", color: active?.id === e.id ? "#F6F1E7" : "#4A4438" }}>{e.title}</button>
          ))}
        </div>
        {active && (
          <>
            <div className="bg-[#F6F1E7] rounded-xl p-3 mb-2 flex items-center justify-center"><QrCode size={110} color="#3E567D" /></div>
            <p className="text-[11px] text-[#6B6456] text-center mb-3">{t("对准来宾电子票二维码扫描，或点击下方名单手动签到（演示环境：每位顾客的电子票二维码各不相同，真实扫描后会自动匹配下方对应的名字）", "Scan a guest's e-ticket QR code, or tap a name below to check in manually (demo only: each guest's QR code is unique — a real scan would auto-match the corresponding name below)")}</p>
            <div className="flex flex-col gap-2">
              {(active.attendees || []).map((a, i) => (
                <button key={i} onClick={() => onToggle(active.id, i)} className="flex items-center justify-between bg-white rounded-xl px-3.5 py-2.5 border border-[#EFE7D6]">
                  <span className="text-[12.5px] text-[#1F2430]">{a.name}</span>
                  {a.checkedIn ? <span className="flex items-center gap-1 text-[11px] text-[#3B5245]"><Check size={13} /> {t("已签到", "Checked in")}</span> : <span className="text-[11px] text-[#6B6456]">{t("待签到", "Not checked in")}</span>}
                </button>
              ))}
              {(!active.attendees || active.attendees.length === 0) && <p className="text-[11px] text-[#6B6456] text-center py-4">{t("该活动暂无报名名单", "No bookings for this event yet")}</p>}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// 管理后台密码——建议改成你自己的密码。
// 注意：这只是"挡住普通客户不小心点进去"的轻量门槛，不是真正的账号系统——
// 因为整个网站的代码是公开可见的静态文件，懂技术的人理论上仍能在源码里找到这个密码。
// 如果以后有真正需要严格保密的后台数据，需要接入正式的登录系统（见开发需求文档"技术架构建议"）。
const ADMIN_PASSWORD = "reddot2026";

function AdminGate({ children, t, lang, setLang }) {
  const [unlocked, setUnlocked] = useState(() => loadPersonal("adminUnlocked", false));
  const [pwd, setPwd] = useState("");
  const [error, setError] = useState("");

  if (unlocked) return children;

  const submit = () => {
    if (pwd === ADMIN_PASSWORD) {
      savePersonal("adminUnlocked", true);
      setUnlocked(true);
    } else {
      setError(t("密码不正确，请重试", "Incorrect password, please try again"));
    }
  };

  return (
    <div className="h-full flex flex-col" style={{ background: "#FFFDF8" }}>
      <TopBar title={t("管理后台", "Admin")} lang={lang} setLang={setLang} />
      <div className="flex-1 min-h-0 overflow-y-auto px-6 py-10 flex flex-col items-center">
        <ShieldCheck size={40} color="#C69A3E" />
        <p className="text-[13px] text-[#1F2430] mt-4 mb-4 text-center">{t("请输入管理员密码", "Please enter the admin password")}</p>
        <input
          type="password" value={pwd}
          onChange={(e) => { setPwd(e.target.value); setError(""); }}
          onKeyDown={(e) => e.key === "Enter" && submit()}
          className="w-full max-w-[280px] bg-[#F1EAD9] rounded-lg px-3 py-2.5 text-[13px] outline-none text-center mb-3"
          placeholder={t("密码", "Password")}
        />
        {error && <p className="text-[11.5px] text-[#E8432D] mb-3">{error}</p>}
        <button onClick={submit} className="w-full max-w-[280px] py-2.5 rounded-full text-[#FFFDF8] font-medium" style={{ background: "#E8432D" }}>
          {t("进入", "Enter")}
        </button>
      </div>
    </div>
  );
}

/* ---------- App 主体 ---------- */
export default function App() {
  const [tab, setTab] = useState("home");
  const [selected, setSelected] = useState(null);
  const [toast, setToast] = useState("");
  const [registrations, setRegistrations] = useState([]);
  const [notifications, setNotifications] = useState([{ text: "欢迎加入红点时光会员！", time: "系统消息" }]);
  const [events, setEvents] = useState(initialEvents);
  const [intro, setIntro] = useState(DEFAULT_INTRO);
  const [introEn, setIntroEn] = useState("");
  const [logo, setLogo] = useState(DEFAULT_LOGO);
  const [photos, setPhotos] = useState([]);
  const [activeMembers, setActiveMembers] = useState(0);
  const [contacts, setContacts] = useState([]);
  const [profile, setProfile] = useState({ name: "", phone: "", email: "" });
  const [lang, setLang] = useState("zh");
  const [loaded, setLoaded] = useState(false);
  const [sharedSyncBlocked, setSharedSyncBlocked] = useState(false);
  const skipFirstSharedSave = useRef(true);

  const t = (zh, en) => (lang === "zh" ? zh : en ?? zh);

  useEffect(() => {
    (async () => {
      const shared = await loadShared();
      // 如果配置了同步网址，但这次没能读到任何数据——很可能是网络问题或暂时连不上，
      // 而不是"这个网站本来就没有数据"。这种情况下绝对不能让后面的自动保存把本地这份
      // 兜底默认数据回写上去，否则会把 Google Sheet 里已经存好的真实数据覆盖掉。
      const loadFailed = !!GOOGLE_SHEET_WEBHOOK_URL && shared === null;
      setSharedSyncBlocked(loadFailed);

      const loadedEvents = shared?.events || initialEvents;
      setEvents(loadedEvents);
      setIntro(shared?.intro || DEFAULT_INTRO);
      setIntroEn(shared?.introEn || "");
      setLogo(shared?.logo || DEFAULT_LOGO);
      setPhotos(shared?.photos || []);
      setActiveMembers(shared?.activeMembers || 0);
      setContacts(shared?.contacts || []);
      setRegistrations(loadPersonal("registrations", []));
      setNotifications(loadPersonal("notifications", [{ text: "欢迎加入红点时光会员！", time: "系统消息" }]));
      setLang(loadPersonal("lang", "zh"));
      setProfile(loadPersonal("profile", { name: "", phone: "", email: "" }));
      setLoaded(true);

      if (loadFailed) {
        notify(t(
          "未能连接到数据服务，当前显示的可能不是最新内容。为避免覆盖真实数据，本次不会自动保存改动，请检查网络后刷新页面重试。",
          "Couldn't connect to the data service — what you're seeing may be out of date. To avoid overwriting real data, changes won't auto-save this session. Please check your connection and refresh."
        ));
      }

      // 深链接：如果是通过分享出去的活动链接（/events/活动ID）直接打开的，
      // 加载完数据后自动跳到对应的活动详情，而不是停在首页
      const m = window.location.pathname.match(/^\/events\/(.+)$/);
      if (m) {
        const found = loadedEvents.find((e) => String(e.id) === m[1]);
        if (found) setSelected(found);
      }
    })();
  }, []);

  // 浏览器地址栏跟随当前打开的活动同步变化，这样分享出去的链接、
  // 以及浏览器的"后退/前进"按钮才能正常工作
  useEffect(() => {
    if (!loaded) return;
    const path = selected ? `/events/${selected.id}` : "/";
    if (window.location.pathname !== path) {
      window.history.pushState({}, "", path);
    }
  }, [selected, loaded]);

  // 支持浏览器的"后退"按钮：从活动详情后退时回到首页
  useEffect(() => {
    const onPopState = () => {
      const m = window.location.pathname.match(/^\/events\/(.+)$/);
      if (m) {
        const found = events.find((e) => String(e.id) === m[1]);
        setSelected(found || null);
      } else {
        setSelected(null);
      }
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, [events]);

  // 活动/公司介绍/Logo/相册/活跃会员数 一起打包同步，减少请求次数
  // 刚加载完的第一次不回写（读到什么就是什么，不需要再存一遍），只在之后真正发生改动时才同步
  useEffect(() => {
    if (!loaded) return;
    if (sharedSyncBlocked) return; // 这次加载数据失败了，绝对不能拿本地这份（可能是兜底默认值）去覆盖服务器上真实的数据
    if (skipFirstSharedSave.current) {
      skipFirstSharedSave.current = false;
      return;
    }
    (async () => {
      const result = await saveShared({ events, intro, introEn, logo, photos, activeMembers, contacts });
      if (!result.ok) {
        // 保存失败了，明确告诉用户，并且暂停后续自动保存——避免又发生"改了半天，其实什么都没真正存上"的情况
        setSharedSyncBlocked(true);
        notify(t(
          "⚠️ 保存失败！刚才的改动可能没有真正存进服务器，请不要关闭页面，检查网络连接后刷新页面重试一次。",
          "⚠️ Save failed! This change may not have actually been saved to the server. Please don't close this page — check your connection and refresh to retry."
        ));
      }
    })();
  }, [events, intro, introEn, logo, photos, activeMembers, contacts, loaded, sharedSyncBlocked]);
  useEffect(() => { if (loaded) savePersonal("registrations", registrations); }, [registrations, loaded]);
  useEffect(() => { if (loaded) savePersonal("notifications", notifications); }, [notifications, loaded]);
  useEffect(() => { if (loaded) savePersonal("lang", lang); }, [lang, loaded]);
  useEffect(() => { if (loaded) savePersonal("profile", profile); }, [profile, loaded]);

  const notify = (text) => { setToast(text); setTimeout(() => setToast(""), 2600); };

  const addRegistration = async (event, info, paymentStatus = "paid") => {
    const qty = Math.max(1, Number(info?.qty) || 1);
    const sync = await syncRegistrationToSheet(event, info, qty, paymentStatus);
    if (!sync.ok) {
      return { ok: false, message: sync.message || t("名额不足，请调整报名人数", "Not enough spots left — please adjust the party size") };
    }
    setRegistrations((r) => [
      { id: event.id, title: event.title, date: event.date, location: event.location, price: event.price * qty, qty, name: info?.name, phone: info?.phone, email: info?.email, paymentStatus },
      ...r,
    ]);
    setNotifications((n) => [{ text: t(`您已成功报名「${event.title}」× ${qty}，活动开始前我们会再次提醒您。`, `You're booked for "${event.title}" × ${qty} — we'll remind you before it starts.`), time: event.date }, ...n]);
    setEvents((evs) => evs.map((e) => e.id === event.id
      ? { ...e, reg: e.reg + qty, attendees: [...(e.attendees || []), { name: info?.name || t("访客", "Guest"), phone: info?.phone || "", email: info?.email || "", qty, checkedIn: false, paymentStatus }] }
      : e));
    if (info?.name || info?.phone || info?.email) {
      setProfile({ name: info?.name || "", phone: info?.phone || "", email: info?.email || "" });
    }
    return { ok: true, message: sync.message || "" };
  };

  const addEvent = (f) => {
    setEvents((evs) => [
      {
        id: Date.now(), type: f.type, tag: f.tag || t("活动", "Event"), title: f.title, date: f.date, location: f.location,
        coords: f.coords || FALLBACK_COORDS, price: Number(f.price) || 0, cap: Number(f.cap) || 0, reg: 0,
        color: f.type === "听见新加坡" ? "#3E567D" : "#3B5245", image: f.image || null,
        desc: f.desc || "", reviews: [], attendees: [],
        titleEn: f.titleEn || "", descEn: f.descEn || "", tagEn: f.tagEn || "",
        originalPrice: f.originalPrice ? Number(f.originalPrice) : null, promoText: f.promoText || "",
      },
      ...evs,
    ]);
  };

  const updateEvent = (id, f) => {
    setEvents((evs) => evs.map((e) => (e.id === id
      ? {
          ...e,
          type: f.type, tag: f.tag || e.tag, title: f.title, date: f.date, location: f.location,
          coords: f.coords || e.coords, price: Number(f.price) || 0, cap: Number(f.cap) || 0,
          color: f.type === "听见新加坡" ? "#3E567D" : "#3B5245",
          image: f.image !== undefined ? f.image : e.image, desc: f.desc || "",
          titleEn: f.titleEn || e.titleEn || "", descEn: f.descEn || e.descEn || "", tagEn: f.tagEn || e.tagEn || "",
          originalPrice: f.originalPrice ? Number(f.originalPrice) : null, promoText: f.promoText || "",
        }
      : e)));
  };

  const setEventCoords = (id, coords) => {
    setEvents((evs) => evs.map((e) => (e.id === id ? { ...e, coords } : e)));
  };

  const deleteEvent = (id, title) => {
    const ok = window.confirm(t(`确定要删除「${title}」吗？此操作不可撤销。`, `Delete "${title}"? This cannot be undone.`));
    if (!ok) return;
    setEvents((evs) => evs.filter((e) => e.id !== id));
    notify(t("活动已删除", "Event deleted"));
  };

  const resetStats = () => {
    const ok = window.confirm(t(
      "确定要清零所有统计数据吗？会把每个活动的已报名人数、签到名单都重置为 0，活跃会员数也会归零。此操作不可撤销，且不会影响 Google Sheet 里已有的报名记录（那份记录仍会保留作为历史存档）。",
      "Reset all stats? This clears each event's booked count and check-in list to zero, and resets active members to zero. This cannot be undone, and does not affect the existing records already in your Google Sheet (those remain as a historical log)."
    ));
    if (!ok) return;
    setEvents((evs) => evs.map((e) => ({ ...e, reg: 0, attendees: [] })));
    setActiveMembers(0);
    notify(t("统计数据已清零", "Stats have been reset"));
  };

  const addReview = (eventId, review) => {
    setEvents((evs) => evs.map((e) => (e.id === eventId ? { ...e, reviews: [review, ...(e.reviews || [])] } : e)));
  };

  const cancelRegistration = (reg, idx) => {
    const ok = window.confirm(t(`确定要取消「${reg.title}」这笔报名吗？`, `Cancel your booking for "${reg.title}"?`));
    if (!ok) return;
    setEvents((evs) => evs.map((e) => {
      if (e.id !== reg.id) return e;
      const qty = reg.qty || 1;
      const attendees = [...(e.attendees || [])];
      const matchIdx = attendees.findIndex((a) => a.name === reg.name && a.phone === reg.phone);
      if (matchIdx > -1) attendees.splice(matchIdx, 1);
      return { ...e, reg: Math.max(0, e.reg - qty), attendees };
    }));
    setRegistrations((rs) => rs.filter((_, i) => i !== idx));
    notify(t("已取消报名", "Booking cancelled"));
  };

  const relocateAllEvents = async () => {
    notify(t("正在批量重新定位所有活动坐标…", "Bulk re-locating all event coordinates…"));
    const results = await Promise.all(
      events.map(async (e) => {
        const coords = await geocodeAddress(e.location);
        return coords ? { ...e, coords } : e;
      })
    );
    setEvents(results);
    notify(t("已尝试重新定位全部活动坐标", "Attempted to re-locate all event coordinates"));
  };

  const toggleAttendee = (eventId, idx) => {
    setEvents((evs) => evs.map((e) => {
      if (e.id !== eventId) return e;
      return { ...e, attendees: e.attendees.map((a, i) => (i === idx ? { ...a, checkedIn: !a.checkedIn } : a)) };
    }));
  };

  const onSaveIntro = async (text, textEn, newLogo, newPhotos) => {
    setIntro(text);
    if (newLogo) setLogo(newLogo);
    if (newPhotos) setPhotos(newPhotos);
    if (textEn) {
      setIntroEn(textEn); // 管理员已经手动填过/改过，直接用，不再自动翻译覆盖
    } else {
      const translated = await translateFields({ intro: text });
      if (translated.intro) setIntroEn(translated.intro);
    }
  };

  let body;
  if (!loaded) {
    body = (
      <div className="h-full flex flex-col items-center justify-center gap-3">
        <img src={logo} alt="红点时光" className="w-14 h-14 rounded-full object-cover animate-pulse" />
        <p className="text-[12px] text-[#6B6456]">{t("正在加载…", "Loading…")}</p>
      </div>
    );
  } else if (selected) {
    const liveEvent = events.find((e) => e.id === selected.id) || selected;
    body = <DetailScreen event={liveEvent} onBack={() => setSelected(null)} notify={notify} addRegistration={addRegistration} addReview={addReview} logo={logo} profile={profile} t={t} lang={lang} setLang={setLang} />;
  } else if (tab === "home") body = <HomeScreen events={events} onOpen={setSelected} logo={logo} t={t} lang={lang} setLang={setLang} />;
  else if (tab === "chat") body = <ChatScreen contacts={contacts} t={t} lang={lang} setLang={setLang} />;
  else if (tab === "profile") body = <ProfileScreen notify={notify} registrations={registrations} notifications={notifications} intro={intro} introEn={introEn} logo={logo} cancelRegistration={cancelRegistration} profile={profile} setProfile={setProfile} t={t} lang={lang} setLang={setLang} />;
  else if (tab === "about") body = <AboutScreen intro={intro} introEn={introEn} logo={logo} photos={photos} contacts={contacts} t={t} lang={lang} setLang={setLang} />;
  else if (tab === "admin")
    body = (
      <AdminGate t={t} lang={lang} setLang={setLang}>
        <AdminScreen events={events} addEvent={addEvent} updateEvent={updateEvent} deleteEvent={deleteEvent} toggleAttendee={toggleAttendee} intro={intro} introEn={introEn} logo={logo} photos={photos} onSaveIntro={onSaveIntro} notify={notify} setEventCoords={setEventCoords} relocateAllEvents={relocateAllEvents} activeMembers={activeMembers} setActiveMembers={setActiveMembers} resetStats={resetStats} contacts={contacts} setContacts={setContacts} sharedSyncBlocked={sharedSyncBlocked} t={t} lang={lang} setLang={setLang} />
      </AdminGate>
    );

  return (
    <div className="w-full h-screen flex justify-center" style={{ background: "#E7DFCC", fontFamily: "'Noto Sans SC', sans-serif" }}>
      <div className="w-full max-w-[400px] h-screen flex flex-col" style={{ background: "#F6F1E7", position: "relative" }}>
        <div className="flex-1 overflow-y-auto min-h-0">{body}</div>
        <BottomNav tab={tab} setTab={setTab} onGoHome={() => setSelected(null)} t={t} />
        <Toast text={toast} />
      </div>
    </div>
  );
}
